 47→	var perPage int
 48→	var cursor string
 49→
 50→	cmd := &cobra.Command{
 51→		Use:   "list",
 52→		Short: "List issues in a project",
 53→		RunE: func(cmd *cobra.Command, args []string) error {
 54→			client, err := f.Client()
 55→			if err != nil {
 56→				return err
 57→			}
 58→			ws, proj, err := f.RequireWorkspaceAndProject()
 59→			if err != nil {
 60→				return err
 61→			}
 62→
 63→			p := api.NewPath(workItemPath()).Workspace(ws).Project(proj)
 64→			p.QueryInt("per_page", perPage)
 65→			p.Query("cursor", cursor)
 66→			p.Query("state", state)
 67→			p.Query("priority", priority)
 68→			p.Query("assignees", assignee)
 69→
 70→			path, err := p.Build()
 71→			if err != nil {
 72→				return err
 73→			}
 74→
 75→			resp, err := client.Get(path)
 76→			if err != nil {
 77→				return err
 78→			}
 79→
 80→			return output.FormatRaw(f.Format, resp, issueColumns)
 81→		},
 82→	}
 83→
 84→	cmd.Flags().StringVar(&state, "state", "", "Filter by state ID")
 85→	cmd.Flags().StringVar(&priority, "priority", "", "Filter by priority (urgent, high, medium, low, none)")
